import{_ as r,o as a,c as o,a2 as n}from"./chunks/framework.YT-FC_Xx.js";const u=JSON.parse('{"title":"延迟与回程","description":"","frontmatter":{},"headers":[],"relativePath":"guide/latency.md","filePath":"guide/latency.md","lastUpdated":1792750293000}'),l={name:"guide/latency.md"};function e(s,t,i,d,g,h){return a(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="延迟与回程" tabindex="-1">延迟与回程 <a class="header-anchor" href="#延迟与回程" aria-label="Permalink to &quot;延迟与回程&quot;">​</a></h1><p>面板可以让每台服务器定时测到国内各地运营商的延迟和丢包，并检测回程走的是哪条线路（CN2 GIA、163、9929、4837、CMI、CMIN2），结果显示在服务器列表和卡片上。</p><h2 id="原理" tabindex="-1">原理 <a class="header-anchor" href="#原理" aria-label="Permalink to &quot;原理&quot;">​</a></h2><ul><li><strong>延迟</strong>：服务器每 3 分钟向每个 <strong>测试点</strong> 发 4 次 TCP 连接，记录平均延迟和丢包。测试点是放在各地运营商机房里的地址，所以测出来的就是“该地区这家运营商的用户到服务器”的延迟，比从面板服务器测准确得多</li><li><strong>回程</strong>：服务器对每个测试点做一次路由追踪，按经过的骨干网判断线路，每天自动检测一次</li></ul><p>不设置测试点时，服务器不测延迟；导入的节点在节点页显示面板服务器到它的延迟，只能作为参考。</p><p>同一台服务器最多同时执行 8 个 TCP 探测，其余自动排队。排队和执行共用超时预算，过期任务会停止；队列已满、排队超时、服务器离线和测试点连接失败会分别显示原因。只升级面板也能用；agent 一起升级后，面板已放弃的探测在服务器上也会停止。</p><p>经中转的线路（前置 → IX → 落地）也有估算的端到端延迟，见 <a href="./relay#延迟">对接中转 - 延迟</a>。</p><h2 id="设置测试点" tabindex="-1">设置测试点 <a class="header-anchor" href="#设置测试点" aria-label="Permalink to &quot;设置测试点&quot;">​</a></h2><p><strong>设置 → 延迟测试点</strong>：</p><ol><li>点 <strong>添加三网推荐</strong> 一键加上广东电信、上海联通、北京移动；或点 <strong>添加预设</strong> 从北京 / 上海 / 广东 × 电信 / 联通 / 移动里挑；也可以 <strong>自定义</strong> 任意域名或 IP 和端口</li><li><strong>默认</strong>：打开的测试点所有服务器都测（单独设置过的服务器除外）</li><li><strong>卡片显示</strong>：最多勾 3 个，卡片上固定显示它们；一个都不勾时显示最差和最好的</li><li>保存后所有服务器马上重测一遍</li></ol><p>最多 30 个测试点。改名会自动同步到单独设置过的服务器。</p><h2 id="给服务器单独设置" tabindex="-1">给服务器单独设置 <a class="header-anchor" href="#给服务器单独设置" aria-label="Permalink to &quot;给服务器单独设置&quot;">​</a></h2><p>不同服务器面向的用户不一样（比如有的只卖移动），可以给服务器单独选测试点：</p><ul><li><strong>单个</strong>：<strong>服务器</strong> 页点服务器的 <strong>测试点</strong></li><li><strong>批量</strong>：<strong>服务器</strong> 页点 <strong>多选</strong>，勾选服务器后点 <strong>测试点</strong>，保存会覆盖这些服务器原来的设置</li></ul><p>选 <strong>跟随默认</strong> 就测 <strong>设置</strong> 里打开“默认”的测试点，那边改了这里跟着变；选 <strong>自定义</strong> 自己勾选，也可以指定这台服务器卡片上固定显示哪几个。一个都不勾就是这台服务器不测延迟和回程，卡片上显示“不测延迟”。</p><h2 id="看结果" tabindex="-1">看结果 <a class="header-anchor" href="#看结果" aria-label="Permalink to &quot;看结果&quot;">​</a></h2><p>延迟和回程显示在 <strong>服务器</strong> 页的服务器列表和卡片上；<strong>节点</strong> 页只给导入的节点显示面板测的延迟，自建入站只显示能不能连上（线路看它所在的服务器）：</p><table tabindex="0"><thead><tr><th>颜色</th><th>含义</th></tr></thead><tbody><tr><td>绿</td><td>低于 100 ms，没有丢包</td></tr><tr><td>黄</td><td>100–300 ms，或有丢包</td></tr><tr><td>红</td><td>300 ms 以上、丢包 50% 以上，或连不上</td></tr></tbody></table><p>每个测试点下面一行是它的回程线路。点延迟打开 <strong>延迟详情</strong>，列出到每个测试点的延迟、丢包和回程，底部有四个按钮：</p><ul><li><strong>重测</strong>：马上测一次</li><li><strong>趋势</strong>：延迟趋势图</li><li><strong>回程</strong>：回程路由详情</li><li><strong>测试点</strong>：给这台服务器单独选测试点</li></ul><h2 id="延迟趋势" tabindex="-1">延迟趋势 <a class="header-anchor" href="#延迟趋势" aria-label="Permalink to &quot;延迟趋势&quot;">​</a></h2><p>点 <strong>趋势</strong>，可以看最近 24 小时、3 天或 7 天里到每个测试点的延迟曲线，下面的表格列出每个测试点的平均延迟、最高延迟和平均丢包，适合看晚高峰是否拥堵。</p><p>历史数据按 <strong>设置 → 服务器与监控 → 监控数据保留天数</strong> 自动清理。</p><h2 id="回程线路" tabindex="-1">回程线路 <a class="header-anchor" href="#回程线路" aria-label="Permalink to &quot;回程线路&quot;">​</a></h2><p>点 <strong>回程</strong> 查看到每个测试点经过的每一跳和识别出的线路，点 <strong>重新检测</strong> 马上测一次。识别规则：</p><table tabindex="0"><thead><tr><th>线路</th><th>依据</th></tr></thead><tbody><tr><td>电信 CN2 GIA</td><td>经过 59.43 段，不经过 202.97</td></tr><tr><td>电信 CN2 GT</td><td>经过 59.43 段，也经过 202.97</td></tr><tr><td>电信 163</td><td>经过 202.97</td></tr><tr><td>联通 9929</td><td>经过 218.105 / 210.51</td></tr><tr><td>联通 4837</td><td>经过 219.158</td></tr><tr><td>移动 CMIN2</td><td>经过 223.118–223.121，且归属 AS58807</td></tr><tr><td>移动 CMI</td><td>经过 223.118–223.121</td></tr></tbody></table><p>IPv6 没有专门的骨干网段，按每一跳的归属网络识别：AS4809 为 CN2（之前没经过电信 AS4134 即 GIA，经过即 GT），AS4134 为电信 163，AS9929 / AS4837 为联通，AS58453 / AS58807 为移动 CMI / CMIN2。</p><ul><li>双栈服务器（有 IPv4 也有 IPv6）对有 IPv6 地址的测试点两条都测：回程详情里每个测试点分 IPv4、IPv6 两行，卡片上显示 IPv4 线路，IPv6 走的不一样时后面多一个小标签（例如“CN2 GT v6 CN2 GIA”）；IPv6 线路变化也会提醒。需要 agent 3.3.28 及以上</li><li>服务器没有 IPv4、或测试点只有 IPv6 地址时自动改用 IPv6 检测，结果旁标 <strong>IPv6</strong>；只有 IPv6 的服务器要选有 IPv6 地址的测试点（域名有 AAAA 记录，或直接填 IPv6 地址）。IPv6 回程需要 agent 3.3.27 及以上</li><li>回程每天自动检测一次，失败的 6 小时后重试；测试点改了，或 agent 升级后会马上重新检测</li><li>需要服务器以 root 运行（或有 NET_RAW 权限），agent 过旧时会提示升级，见 <a href="./upgrade#agent-升级">升级</a></li><li>目标不回应时只显示到最后一个有回应的路由器；没经过上面的骨干网显示“未识别”</li></ul><h2 id="告警" tabindex="-1">告警 <a class="header-anchor" href="#告警" aria-label="Permalink to &quot;告警&quot;">​</a></h2><p>在 <a href="./notify">通知</a> 里勾选：</p><ul><li><strong>延迟 / 丢包异常</strong>：某个测试点连续 3 次（约 9 分钟）丢包超过阈值（默认 20%），或延迟超过阈值（可选，默认不按延迟提醒），恢复时也会通知</li><li><strong>回程线路变化</strong>：每天检测回程时对比上一次，例如 CN2 GIA 变成 163</li></ul><h2 id="连通性检测" tabindex="-1">连通性检测 <a class="header-anchor" href="#连通性检测" aria-label="Permalink to &quot;连通性检测&quot;">​</a></h2><p>和测试点无关，面板服务器每 3 分钟会连一次节点页上的所有节点，包括导入的节点和面板搭建的入站，看端口能不能连上。节点页上方 <strong>更多 → 检测节点连通性</strong> 可以马上测一遍：</p><ul><li>连得上：自建入站显示“可连接”，导入的节点显示面板到它的延迟</li><li>连不上：红点，并显示原因（连接超时、域名解析失败、无法连接）</li></ul><p>面板搭建的入站按 <strong>分享地址</strong> 检测，没填分享地址时用所在服务器的 IP。内核在跑但连不上，通常是云服务商的安全组或防火墙没有放行这个端口。服务器离线或内核没在运行时不检测，只显示服务器或内核的状态（这两种情况本来就有各自的提醒）。</p><p>检测是从 <strong>面板服务器</strong> 发起的 TCP 连接，只能作为参考：面板连不上不代表中转机或客户端也连不上，反之亦然。以下几种不检测，不显示状态：</p><ul><li>Hysteria2、TUIC：只用 UDP，无法这样检测</li><li>开启了“仅允许中转机访问（防火墙白名单）”的入站：面板服务器不在白名单里，必然连不上</li><li>只监听本机（127.0.0.1）的入站</li></ul><p>面板服务器没有 IPv6 时（常见于 Docker 部署），连不了只有 IPv6 的节点。这种情况不算连不上，也不发提醒：面板搭建的入站改由所在服务器自己连一下这个地址和端口，显示“服务器自检（面板没有 IPv6）”；服务器自检只能确认内核在这个地址上监听，确认不了云服务商的防火墙有没有放行。导入的节点没有 agent，这种情况下不检测。</p><p>开启 <a href="./notify">通知</a> 后，节点连续两次连不上会推送提醒。</p>',39)])])}const P=r(l,[["render",e]]);export{u as __pageData,P as default};
